<h1>Gallery albums</h1><p>Albums and images reuse tenant-owned media IDs. Published records require public gallery images.</p><?php foreach(session('errors')??[] as $error): ?><p><?= esc($error) ?></p><?php endforeach ?><ul><?php foreach($albums as $album): ?><li><a href="?id=<?= esc($album['id']) ?>"><?= esc($album['title']) ?></a> — <?= esc($album['status']) ?><form class="inline-form" method="post" action="<?= site_url('tenant/website/institutional/gallery/albums/'.$album['id'].'/archive') ?>"><?= csrf_field() ?><button>Archive</button></form></li><?php endforeach ?></ul>
<form method="post" action="<?= site_url('tenant/website/institutional/gallery/albums') ?>"><?= csrf_field() ?><?php if($selected): ?><input type="hidden" name="id" value="<?= esc($selected['id']) ?>"><?php endif ?><label>Album title <input name="title" required value="<?= esc(old('title',$selected['title']??'')) ?>"></label><label>Slug <input name="slug" required pattern="[a-z0-9-]+" value="<?= esc(old('slug',$selected['slug']??'')) ?>"></label><label>Description <textarea name="description" required><?= esc(old('description',$selected['description']??'')) ?></textarea></label><label>Category <input name="category" required value="<?= esc(old('category',$selected['category']??'')) ?>"></label><label>Cover media ID <input name="cover_media_id" required inputmode="numeric" value="<?= esc(old('cover_media_id',$selected['cover_media_id']??'')) ?>"></label><label>Order <input name="sort_order" type="number" min="0" required value="<?= esc(old('sort_order',$selected['sort_order']??0)) ?>"></label><label>Status <select name="status"><?php foreach(['draft','published','archived'] as $status): ?><option<?= old('status',$selected['status']??'draft')===$status?' selected':'' ?>><?= esc($status) ?></option><?php endforeach ?></select></label><button>Save album</button></form>
<?php if($selected): ?><h2>Ordered images</h2><form method="post" action="<?= site_url('tenant/website/institutional/gallery/items') ?>"><?= csrf_field() ?><input type="hidden" name="gallery_album_id" value="<?= esc($selected['id']) ?>"><label>Media ID <input name="media_file_id" required inputmode="numeric"></label><label>Caption <input name="caption" required></label><label>Alternative text <input name="alt_text" required></label><label>Order <input name="sort_order" type="number" min="0" required value="0"></label><input type="hidden" name="status" value="published"><button>Add image</button></form><form method="post" action="<?= site_url('tenant/website/institutional/gallery/albums/'.$selected['id'].'/reorder') ?>"><?= csrf_field() ?><?php foreach($items as $item): ?><p><input name="item_ids[]" value="<?= esc($item['id']) ?>"> <?= esc($item['caption']) ?></p><?php endforeach ?><button>Save displayed order</button></form><?php foreach($items as $item): ?><form class="inline-form" method="post" action="<?= site_url('tenant/website/institutional/gallery/items/'.$item['id'].'/remove') ?>"><?= csrf_field() ?><button>Remove <?= esc($item['caption']) ?></button></form><?php endforeach ?><?php endif ?>
<h2>Reusable gallery images</h2><ul><?php foreach($media as $file): ?><li>ID <?= esc($file['id']) ?> — <?= esc($file['original_name']) ?> — <?= esc($file['visibility']) ?></li><?php endforeach ?></ul><?= $this->endSection() ?>
